// Generates js/native-namespace.d.ts: an interface with one member per global
// that NativeScript declares (UIView, CGRectMake, interop, …), so `native.X`
// is typed. (`typeof globalThis` can't do this: TS leaves class/let/const
// declarations off it.)
//
//   node scripts/gen-native-types.mjs
import { readFileSync, readdirSync, writeFileSync } from "node:fs";

// Declarations generated by the same patched NativeScript build as the add-on
// (scripts/build-nativescript.sh copies them here), so names match the runtime.
const root = "nativescript/types";
const files = [
  ...readdirSync(`${root}/ios`).filter((f) => f.endsWith(".d.ts")).map((f) => `${root}/ios/${f}`),
  `${root}/objc/index.d.ts`,
];

const names = new Set();
for (const file of files) {
  const source = readFileSync(file, "utf8");
  // Top-level `declare …` in the SDK files, and members of `declare global { … }`.
  for (const m of source.matchAll(/^(?:declare\s+|\s{2})(?:abstract\s+)?(?:class|function|var|const|let|enum|namespace)\s+([A-Za-z_$][\w$]*)/gm)) {
    names.add(m[1]);
  }
}

const members = [...names].sort().map((name) => `  ${name}: typeof ${name};`);
writeFileSync(
  "js/native-namespace.d.ts",
  `// Generated by scripts/gen-native-types.mjs — do not edit.
/// <reference path="../nativescript/types/objc/index.d.ts" />
/// <reference path="../nativescript/types/ios/index.d.ts" />
export interface NativeNamespace {
${members.join("\n")}
}
`,
);
console.log(`js/native-namespace.d.ts: ${members.length} members`);
